"""Policy language: lexing, parsing and the declared static bounds.

The public language is zero or more ``PREDICATE ACTION ;`` rules whose
predicates concern sequences of registered *services*, not characters.
This module only recognises syntax and enforces the declared limits; it never
evaluates predicates and never builds automata (see ``compiler.compiler``).

Recognised predicates::

    match(PATH)  startswith(PATH)  endswith(PATH)  contains(PATH)
    (P and P)    (P or P)          not(P)

Only space, tab, form feed, CR and LF are ignored *between* tokens; vertical
tab and every other Unicode whitespace character is forbidden anywhere in a
policy string.  Characters inside a service name are never ignored.
"""
import re

__all__ = ['PolicyError', 'parse', 'RULE_LIMITS']


class PolicyError(Exception):
    """Lexical, syntactic or declared-bound violation of the policy language."""


# ---------------------------------------------------------------- lexing ----
_ALLOWED_CHARS = frozenset(
    ' \t\n\r\fABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789(),;')
_TOKEN = re.compile(r'[A-Za-z0-9]+|[(),;]')
_NAME = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}').fullmatch
_ATOMS = frozenset(('match', 'startswith', 'endswith', 'contains'))

# Declared per-string bounds (see PROTOCOL.md "Policy language and images").
MAX_DEPTH = 16             # predicate nesting depth; an atom has depth 1
MAX_PATH = 16              # services in one path
MAX_COMPLEX_RULES = 8      # rules whose predicate is not a single match atom
MAX_COMPLEX_ATOMS = 32     # atom occurrences inside one complex predicate
MAX_DISTINCT_NONMATCH = 4  # distinct non-match atoms per string
MAX_NONMATCH_PATH = 4      # services in a non-match atom path
MAX_ATOMS = 32768          # atom occurrences per string
MAX_PATHS = 65536          # path-service occurrences per string
MAX_RULES = MAX_ATOMS      # every rule contains at least one atom
_TOKEN_CAP = 500000        # a valid string never needs more tokens than this

RULE_LIMITS = {
    'max_depth': MAX_DEPTH, 'max_path': MAX_PATH,
    'max_complex_rules': MAX_COMPLEX_RULES, 'max_complex_atoms': MAX_COMPLEX_ATOMS,
    'max_distinct_nonmatch': MAX_DISTINCT_NONMATCH, 'max_nonmatch_path': MAX_NONMATCH_PATH,
    'max_atoms': MAX_ATOMS, 'max_paths': MAX_PATHS,
}


class _Stream(object):
    """One-token-lookahead lexer over a charset-validated policy string."""
    __slots__ = ('_find', 'tok', 'count')

    def __init__(self, text):
        self._find = _TOKEN.finditer(text)
        self.count = 0
        self.tok = self._pull()

    def _pull(self):
        m = next(self._find, None)
        if m is None:
            return None
        self.count += 1
        if self.count > _TOKEN_CAP:
            raise PolicyError('token budget')
        return m.group()

    def take(self):
        tok = self.tok
        self.tok = self._pull()
        return tok


# --------------------------------------------------------------- parsing ----
def _predicate(stream, allowance):
    """Parse one predicate.

    ``allowance`` is the maximum nesting depth this subtree may use; an atom
    consumes one level and each wrapper one level on top of its child.
    Returns ``(node, atoms, path_services, nonmatch_atoms)``.
    """
    if allowance < 1:
        raise PolicyError('nesting depth')
    tok = stream.tok
    if tok == '(':
        if allowance < 2:
            raise PolicyError('nesting depth')
        stream.take()
        left, la, lp, ln = _predicate(stream, allowance - 1)
        op = stream.take()
        if op != 'and' and op != 'or':
            raise PolicyError('binary operator')
        right, ra, rp, rn = _predicate(stream, allowance - 1)
        if stream.take() != ')':
            raise PolicyError('closing parenthesis')
        return (op, left, right), la + ra, lp + rp, ln + rn
    if tok == 'not':
        if allowance < 2:
            raise PolicyError('nesting depth')
        stream.take()
        if stream.take() != '(':
            raise PolicyError('opening parenthesis')
        inner, a, p, nonmatch = _predicate(stream, allowance - 1)
        if stream.take() != ')':
            raise PolicyError('closing parenthesis')
        return ('not', inner), a, p, nonmatch
    if tok in _ATOMS:
        stream.take()
        if stream.take() != '(':
            raise PolicyError('opening parenthesis')
        names = []
        if stream.tok == ')':
            stream.take()
        else:
            while True:
                name = stream.take()
                if name is None or _NAME(name) is None:
                    raise PolicyError('path service')
                names.append(name)
                sep = stream.take()
                if sep == ',':
                    continue
                if sep == ')':
                    break
                raise PolicyError('path separator')
        path = tuple(names)
        if len(path) > MAX_PATH:
            raise PolicyError('path length')
        if tok != 'match':
            if len(path) > MAX_NONMATCH_PATH:
                raise PolicyError('non-match path length')
            nonmatch = ((tok, path),)
        else:
            nonmatch = ()
        return (tok, path), 1, len(path), nonmatch
    raise PolicyError('predicate')


def parse(text):
    """Parse ``text`` and enforce every declared bound.

    Returns ``(rules, atoms, path_services)`` where ``rules`` is a list of
    ``(predicate, allow_flag)`` pairs and a predicate node is one of
    ``(kind, path)``, ``('and', l, r)``, ``('or', l, r)``, ``('not', x)``.
    Raises :class:`PolicyError` for any lexical, syntactic or bound problem.
    """
    if not set(text) <= _ALLOWED_CHARS:
        raise PolicyError('forbidden character')
    if text.count(';') > MAX_RULES:
        # A valid string has one rule per ';', each holding at least one atom.
        raise PolicyError('rule budget')
    stream = _Stream(text)
    rules = []
    atoms = 0
    paths = 0
    complex_rules = 0
    nonmatch = set()
    while stream.tok is not None:
        predicate, a, p, new_nonmatch = _predicate(stream, MAX_DEPTH)
        atoms += a
        paths += p
        if atoms > MAX_ATOMS:
            raise PolicyError('atom budget')
        if paths > MAX_PATHS:
            raise PolicyError('path-service budget')
        if predicate[0] != 'match':
            complex_rules += 1
            if complex_rules > MAX_COMPLEX_RULES:
                raise PolicyError('complex rule budget')
            if a > MAX_COMPLEX_ATOMS:
                raise PolicyError('complex atom budget')
        if new_nonmatch:
            nonmatch.update(new_nonmatch)
            if len(nonmatch) > MAX_DISTINCT_NONMATCH:
                raise PolicyError('distinct non-match atom budget')
        action = stream.take()
        if action != 'allow' and action != 'drop':
            raise PolicyError('action')
        if stream.take() != ';':
            raise PolicyError('rule terminator')
        rules.append((predicate, action == 'allow'))
    return rules, atoms, paths
